def comps(g):
    seen=[[False]*len(r) for r in g]; out={}
    def dfscells(cells):
        stack=list(cells); res=[]
        while stack:
            y,x=stack.pop()
            if seen[y][x]: continue
            seen[y][x]=True
            val=g[y][x]; res.append((y,x,val))
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<len(g) and 0<=nx<len(g[0]) and not seen[ny][nx] and g[ny][nx]==val:
                        stack.append((ny,nx))
        return res
    for y,x,v in [(y,x,g[y][x]) for y in range(len(g)) for x in range(len(g[0]))]:
        if v==0: continue
        cs=dfscells([(y,x)]); key=v
        out.setdefault(key,[]).extend(cs)
    return out
